using Godot;
using System;
using System.Linq;
using System.Collections.Generic;
using HakutaiKagami.Core.Contracts;
public partial class NewGameRuntime
{
 int craftTab;long craftQuantity=2,voyageQuantity=20;string voyageGood="wood";string craftGood="iron";EntityId? craftDestination;readonly Dictionary<string,Button> craftReviewButtons=new();
 internal void ReviewCraftCategory(int category){craftTab=category;ShowCraftTrade();}
 internal void ReviewCraftPress(string key)=>craftReviewButtons[key].EmitSignal(Button.SignalName.Pressed);
 void ShowCraftTrade(){if(IsSaving||IsClockControlling)return;var(box,rev)=SocialWindow("職人・原料・航海と教会");craftReviewButtons.Clear();var w=Snapshot();var actor=Session.PlayerControl;if(SocialWorld.Site(w,actor) is not {} site){{}return;}if(!MaterialMarkets.Sites(w).Contains(site)){{}return;}var faction=HouseSuccession.Factions(w).FirstOrDefault(f=>f.Head==actor.Value);var owner=new EntityId(faction?.Id??"org:none");
 EntityId Nonce(string key)=>new("request:craft-ui/"+rev+"/"+key.Replace(':','/'));
 void Button(string key,string text,Func<CraftInput> input){var b=new Button{Text=text};box.AddChild(b);craftReviewButtons[key]=b;b.Pressed+=()=>{if(IsSaving||IsClockControlling)return;CancelAdvancePrefetch();var result=Session.ManageCraft(input(),rev);message.Text=result.VisibleReason;Refresh();ShowCraftTrade();};}
 var tabs=new OptionButton();foreach(var text in new[]{"職人との相談・工房","原料・製品の取引と運搬","交易船と港","宣教師と個人の信仰"})tabs.AddItem(text);tabs.Select(craftTab);box.AddChild(tabs);tabs.ItemSelected+=v=>{craftTab=(int)v;ShowCraftTrade();};SocialText(box,NewGameWorld.SiteName(site.Value)+"");
 if(craftTab==0){var destinations=w.NewGame!.Start.Castles.Where(c=>c.Faction==owner.Value).Select(c=>new EntityId(c.Id)).ToArray();if(destinations.Length>0){if(craftDestination==null||!destinations.Contains(craftDestination.Value))craftDestination=destinations.Contains(site)?site:destinations[0];var to=new OptionButton();foreach(var d in destinations)to.AddItem(NewGameWorld.SiteName(d.Value));to.Select(Array.IndexOf(destinations,craftDestination.Value));box.AddChild(to);to.ItemSelected+=v=>craftDestination=destinations[(int)v];}
 foreach(var group in CraftTrade.LocalGroups(w,actor)){var pos=CraftTrade.Position(w,group.Id);SocialText(box,group.Name+"／"+group.People+"人の一座。武将や軍を増やすものではありません。");if(pos.Owner==null){Button("meet-"+group.Id.Value,"一座の長と、住まい・給付・仕事の条件を相談する",()=>new(Nonce("meet"),CraftAction.MeetGroup,owner,site,group.Id));if(destinations.Length>0)Button("hire-"+group.Id.Value,"屋敷と特権を認め、給付50文と現地の移動食を私財で用意して招く",()=>new(Nonce("hire"),CraftAction.Hire,owner,site,group.Id,craftDestination));}
 else if(pos.Owner==owner){if(pos.Stopped&&pos.Destination!=null)Button("resume-"+group.Id.Value,"現地で道を確かめ、同じ一座の移動を再開する",()=>new(Nonce("resume"),CraftAction.ResumeGroup,owner,site,group.Id,pos.Destination));else foreach(var recipe in CraftTrade.Recipes.Where(r=>r.Skill==group.Skill))Button("produce-"+recipe.Good,CraftTrade.Name(recipe.Good)+"を製作（"+recipe.Seconds/86400+"日・米"+recipe.Rice+"kg・銭"+recipe.Coins+"文）",()=>new(Nonce("produce-"+recipe.Good),CraftAction.Produce,owner,site,group.Id,Good:recipe.Good));Button("renew-"+group.Id.Value,"給付の満期後に、一年分を現地で更新する",()=>new(Nonce("renew"),CraftAction.RenewPay,owner,site,group.Id));}}
 foreach(var recipe in CraftTrade.Recipes){long count=CraftTrade.Stock(w,owner,site,recipe.Good);if(count>0)SocialText(box,"蔵にある完成品："+CraftTrade.Name(recipe.Good)+" "+count);}
 foreach(var hire in w.Crafts?.Entries.Where(e=>e.Actor==actor&&e.Input.Action==CraftAction.Hire&&e.Accepted&&e.Input.Destination!=site)??[]){if(CraftTrade.Position(w,hire.Input.Reference!.Value).Site!=site)SocialText(box,"招請した一座：行先 "+NewGameWorld.SiteName(hire.Input.Destination!.Value.Value)+"");}
 }
 else if(craftTab==1){if(faction==null){{}return;}var goods=new OptionButton();var list=CraftTrade.RawGoods.Concat(CraftTrade.Recipes.Select(r=>r.Good)).Distinct().ToArray();foreach(var good in list)goods.AddItem(CraftTrade.Name(good));goods.Select(Array.IndexOf(list,craftGood));box.AddChild(goods);goods.ItemSelected+=v=>{craftGood=list[(int)v];ShowCraftTrade();};var quantity=new SpinBox{MinValue=1,MaxValue=20,Step=1,Value=craftQuantity,Prefix="数量："};box.AddChild(quantity);quantity.ValueChanged+=v=>craftQuantity=(long)v;
 if(CraftTrade.RawGoods.Contains(craftGood))Button("buy-raw","現地の原料商から家の銭で買い、蔵に受け取る",()=>new(Nonce("buy"),CraftAction.Buy,owner,site,Good:craftGood,Quantity:craftQuantity));Button("sell-stock","選んだ現地の実在庫を原料商へ売る（買値より低い売値）",()=>new(Nonce("sell"),CraftAction.Sell,owner,site,Good:craftGood,Quantity:craftQuantity));Button("load-raw","この原料・製品を本人の携行枠100kgに積む",()=>new(Nonce("load"),CraftAction.Load,owner,site,Good:craftGood,Quantity:craftQuantity));foreach(var good in list)SocialText(box,CraftTrade.Name(good)+"：蔵"+CraftTrade.Stock(w,owner,site,good)+"／原料商の在庫"+CraftTrade.MerchantStock(w,site,good)+"／単価"+CraftTrade.UnitPrice(w,site,good)+"文");foreach(var cargo in CraftTrade.Carried(w,actor))Button("unload-"+cargo.Input.Id.Value,CraftTrade.Name(cargo.Input.Good)+" "+cargo.Input.Quantity+"を現地の自家の蔵へ荷下ろしする",()=>new(Nonce("unload"),CraftAction.Unload,owner,site,cargo.Input.Id));}
 else if(craftTab==2){{}var cargoGoods=CraftTrade.Recipes.Select(r=>r.Good).Prepend("wood").ToArray();var cargoPick=new OptionButton();foreach(var g in cargoGoods)cargoPick.AddItem(CraftTrade.Name(g));cargoPick.Select(Array.IndexOf(cargoGoods,voyageGood));box.AddChild(cargoPick);cargoPick.ItemSelected+=v=>{voyageGood=cargoGoods[(int)v];voyageQuantity=Math.Min(voyageQuantity,1000/CraftTrade.Mass(voyageGood));ShowCraftTrade();};var amount=new SpinBox{MinValue=1,MaxValue=Math.Min(20,1000/CraftTrade.Mass(voyageGood)),Step=1,Value=voyageQuantity,Prefix="積荷の数量："};box.AddChild(amount);amount.ValueChanged+=v=>voyageQuantity=(long)v;SocialText(box,"選択中の積荷の取引額目安："+CraftTrade.Price(voyageGood)*voyageQuantity*2+"文。ここから準備費・米・荷の取得費がかかります。小口では費用割れします。受領額は相手の実際の支払能力で決まり、残りは未払い原本に残ります。");Button("meet-merchant","現地の商人と航海・積荷を相談する",()=>new(Nonce("merchant"),CraftAction.MeetMerchant,owner,site));foreach(var ship in PublicWorks.Ships(w).Where(s=>s.Owner==owner&&s.Port==site&&s.Kind==WorksKind.TradeShip))Button("launch-"+ship.Id.Value,"選んだ実在の荷を保守済みの交易船へ積み、沿岸航海へ出す",()=>new(Nonce("launch"),CraftAction.LaunchVoyage,owner,site,ship.Id,Good:voyageGood,Quantity:voyageQuantity));foreach(var voyage in CraftTrade.Voyages(w).Where(v=>v.Owner==owner&&v.Port==site)){bool returned=voyage.Phase is "帰港・決済済み" or "帰港・代金一部未払い" or "取りやめ・荷戻し済み";var launch=w.Crafts!.Entries.Single(e=>e.Input.Id==voyage.Id);var timing=CraftTrade.VoyageTiming(w,launch,w.ElapsedSeconds);SocialText(box,returned?voyage.Phase:timing.Home?"出航準備・港で確認できる状態":"運航中。帰港先からの結果はまだ未確認");if(voyage.Phase=="帰港・代金一部未払い")Button("debt-"+voyage.Id.Value,"実帰港の未払い代金を現地で受け取る",()=>new(Nonce("debt"),CraftAction.CollectTradeDebt,owner,site,voyage.Id));if(!returned&&(w.ElapsedSeconds<launch.Legs[0].StartAt||timing is {Waiting:true,Home:true}))Button("cancel-"+voyage.Id.Value,"港で出航を取りやめ、同じ荷を蔵へ戻す",()=>new(Nonce("cancel"),CraftAction.CancelVoyage,owner,site,voyage.Id));}}
 else {if(PublicWorks.Land(w,site).Port==0){{}return;}var mission=CraftTrade.Mission(site);SocialText(box,mission.Name+"");if(faction!=null){Button("permit-mission","この港で布教を認める",()=>new(Nonce("permit"),CraftAction.PermitMission,owner,site));Button("revoke-mission","この港の布教許可を取りやめる",()=>new(Nonce("revoke"),CraftAction.PermitMission,owner,site,Allow:false));}SocialText(box,"現地の布教許可："+(CraftTrade.PermittedMission(w,site)?"認められている":"まだ認められていない")+"／本人の入信："+(CraftTrade.Christian(w,actor)?"入信した記録あり":"記録なし"));if(!CraftTrade.Christian(w,actor))Button("join-faith","本人の選択として入信する（主従や所領は変わらない）",()=>new(Nonce("faith"),CraftAction.JoinFaith,owner,site));}
 }
}
